func (l Layout) Data() string        { return filepath.Join(string(l), "data") }
func (l Layout) Bundle() string      { return filepath.Join(string(l), "bundle") }
func (l Layout) TLS() string         { return filepath.Join(string(l), "tls") }
func (l Layout) Key() string         { return filepath.Join(l.TLS(), "member.key") }
func (l Layout) Certificate() string { return filepath.Join(l.TLS(), "member.pem") }
func (l Layout) CA() string          { return filepath.Join(l.TLS(), "ca.pem") }

// Env is the member's environment: the profile settings, the host-owned paths
// and member, the member's name.
func (l Layout) Env(env map[string]string, profile Profile, member string) map[string]string {
	result := maps.Clone(env)
	result[EnvNodeName] = member
	result[EnvDataDirectory] = l.Data()
	result[EnvBundleExtract] = l.Bundle()
	result[EnvPeerCertificate] = l.Certificate()
	result[EnvPeerPrivateKey] = l.Key()
	result[EnvPeerClientCA] = l.CA()
	if profile.ClientPort != 0 {
		result[EnvClientCertificate] = l.Certificate()
		result[EnvClientPrivateKey] = l.Key()
	}
	return result
}

func Healthy(ctx context.Context, adminPort int) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(adminPort)+"/healthz", nil)
	if err != nil {
		return err
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase health: %w", err)
	}
	defer response.Body.Close()
	var body struct {
		Status string `json:"status"`
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, 4096))
	if err == nil && response.StatusCode == http.StatusOK {
		err = json.Unmarshal(data, &body)
	}
	if err != nil || response.StatusCode != http.StatusOK || body.Status != "ok" {
		return fmt.Errorf("terrabase health: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

binary_identity.text:
func NewCA(cell string, now time.Time) (certificatePEM, keyPEM []byte, err error) {
	if !nameRE.MatchString(cell) {
		return nil, nil, errors.New("invalid cell name")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: "TerraBase member CA " + cell},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: now.Add(caValidity),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageCRLSign,
		BasicConstraintsValid: true, IsCA: true, MaxPathLenZero: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, template, template, &key.PublicKey, key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), nil
}

// LoadCA reads a member CA written by NewCA. The key must be a regular
// file that only this process user owns and can read.
func LoadCA(certificateFile, keyFile string) (*CA, error) {
	certificatePEM, err := os.ReadFile(certificateFile)
	if err != nil {
		return nil, err
	}
	keyPEM, err := readOwnerOnly(keyFile)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA key: %w", err)
	}
	pair, err := tls.X509KeyPair(certificatePEM, keyPEM)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA: %w", err)
	}
	certificate := pair.Leaf
	signer, ok := pair.PrivateKey.(crypto.Signer)
	if len(pair.Certificate) != 1 || !ok || !certificate.IsCA || certificate.KeyUsage&x509.KeyUsageCertSign == 0 {
		return nil, errors.New("terrabase member CA must be one CA certificate and its key")
	}
	return &CA{certificate: certificate, pem: certificatePEM, key: signer}, nil
}

func (ca *CA) CertificatePEM() []byte { return slices.Clone(ca.pem) }

// Issue signs a member's certificate request for its listed peer entry. The
// certificate names the member and its peer address, and serves both as the
// peer listener's server certificate and as the client certificate a member
// presents to other members.
func (ca *CA) Issue(csrDER []byte, peer Peer, now time.Time) ([]byte, error) {
	request, err := x509.ParseCertificateRequest(csrDER)
	if err != nil || request.CheckSignature() != nil {
		return nil, errors.New("invalid member certificate request")
	}
	if key, ok := request.PublicKey.(*ecdsa.PublicKey); !ok || key.Curve != elliptic.P256() {
		return nil, errors.New("member certificate request must use an ECDSA P-256 key")
	}
	notAfter := now.Add(memberValidity)
	if ca.certificate.NotAfter.Before(notAfter) {
		notAfter = ca.certificate.NotAfter
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: peer.Name},
		DNSNames: []string{peer.Name}, IPAddresses: []net.IP{peer.Address.Addr().AsSlice()},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: notAfter,
		KeyUsage:    x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
	}
	der, err := x509.CreateCertificate(rand.Reader, template, ca.certificate, request.PublicKey, ca.key)
	if err != nil {
		return nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), nil
}

// NewMemberKey creates a member's private key and the certificate request
// the host sends to the controller. The key never leaves the host.
func NewMemberKey() (keyPEM, csrDER []byte, err error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	csrDER, err = x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{}, key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), csrDER, nil
}

release_verification.text:
func VerifyRelease(binaryPath, checksumPath string) (string, error) {
	return VerifyAsset(binaryPath, checksumPath, assetRE)
}

// VerifyAsset is VerifyRelease for any single-file release executable whose
// asset name matches asset, such as ts-auth-linux-arm64.
func VerifyAsset(binaryPath, checksumPath string, asset *regexp.Regexp) (string, error) {
	name := filepath.Base(binaryPath)
	if !asset.MatchString(name) {
		return "", fmt.Errorf("release executable %q is not one of %s", name, asset)
	}
	checksum, err := os.ReadFile(checksumPath)
	if err != nil {
		return "", err
	}
	fields := strings.Fields(string(checksum))
	if len(fields) != 2 || bytes.Count(checksum, []byte("\n")) > 1 || strings.TrimPrefix(fields[1], "*") != name ||
		len(fields[0]) != 64 || strings.ToLower(fields[0]) != fields[0] {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	if _, err := hex.DecodeString(fields[0]); err != nil {
		return "", fmt.Errorf("%s is not one sha256sum line for %s", checksumPath, name)
	}
	file, err := os.Open(binaryPath)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	// The asset name is the architecture the hosts run: an executable built
	// for another machine would otherwise fail only once it reached them.
	var header elf.Header64
	if err := binary.Read(io.TeeReader(file, hash), binary.LittleEndian, &header); err != nil || string(header.Ident[:4]) != elf.ELFMAG {
		return "", fmt.Errorf("%s is not an ELF executable", binaryPath)
	}
	if elf.Class(header.Ident[elf.EI_CLASS]) != elf.ELFCLASS64 || elf.Data(header.Ident[elf.EI_DATA]) != elf.ELFDATA2LSB {
		return "", fmt.Errorf("%s is not a 64-bit little-endian ELF executable", binaryPath)
	}
	want := map[string]elf.Machine{"amd64": elf.EM_X86_64, "arm64": elf.EM_AARCH64}[name[strings.LastIndexByte(name, '-')+1:]]
	if got := elf.Machine(header.Machine); got != want {
		return "", fmt.Errorf("%s must be built for %v, found %v", name, want, got)
	}
	size, err := io.Copy(hash, io.LimitReader(file, maxBinaryBytes))
	if err != nil {
		return "", err
	}
	if size+int64(binary.Size(header)) > maxBinaryBytes {
		return "", errors.New("release executable exceeds the artifact admission limit")
	}
	if digest := hex.EncodeToString(hash.Sum(nil)); digest != fields[0] {
		return "", fmt.Errorf("%s has SHA-256 %s, its release checksum says %s", name, digest, fields[0])
	}
	return fields[0], nil
}

qualification_gate.text:
// Env names the test tier of the current run.
const Env = "TS_TEST_TIER"

// QualificationTier is the Env value of a pre-deploy qualification run.
const QualificationTier = "qualification"

// Qualifying reports whether this run is a T2 qualification run.
func Qualifying() bool { return os.Getenv(Env) == QualificationTier }

func Qualification(t testing.TB, envs ...string) []string {
	t.Helper()
	if len(envs) == 0 {
		t.Fatal("tier.Qualification needs the environment variables that supply its fixture")
	}
	values := make([]string, len(envs))
	var missing []string
	for i, name := range envs {
		values[i] = os.Getenv(name)
		if values[i] == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		Unavailable(t, "qualification fixture not supplied: set %s", strings.Join(missing, ", "))
	}
	return values
}

// Unavailable reports that a T2 fixture is missing for a reason the caller
// determined itself, such as an opt-in that needs one of several variables.
// It skips the test, or fails it in a qualification run.
func Unavailable(t testing.TB, format string, args ...any) {
	t.Helper()
	if Qualifying() {
		t.Fatalf(Env+"="+QualificationTier+": "+format, args...)
	}
	t.Skipf(format, args...)
}

data_volume_cli.text:
func Run(ctx context.Context, args []string, output io.Writer) error {
	if len(args) > 0 {
		switch args[0] {
		case "data-volume":
			return runDataVolume(ctx, args[1:], output)
		case "restore-volume":
			return runRestoreVolume(ctx, args[1:], output)
		case "restore-check":
			return runRestoreCheck(ctx, args[1:], output)
		case "__restore-check":
			return runIsolatedRestoreCheck(ctx, os.Stdin, output)
		}

func runDataVolume(ctx context.Context, args []string, output io.Writer) error {
	flags := flag.NewFlagSet("terrabase data-volume", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	planPath := flags.String("plan", "", "cell plan, for example deploy/oci-region/plan.json")
	member := flags.String("member", "", "member name, for example gru-1-db-1")
	instance := flags.String("instance", "", "OCID of the running instance named --member")
	grow := flags.Int64("grow-gb", 0, "grow the existing volume to this size instead of attaching")
	compartment := flags.String("compartment", "", "workload compartment OCID; defaults to the plan's resource_ids.workload_compartment")
	apply := flags.Bool("apply", false, "perform the OCI calls; without it only print the request")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if flags.NArg() != 0 || *planPath == "" || *member == "" || (*instance == "") == (*grow == 0) {
		return errors.New("data-volume requires --plan, --member and exactly one of --instance or --grow-gb")
	}
	wire, err := os.ReadFile(*planPath)
	if err != nil {
		return err
	}
	request, err := resolveDataVolume(wire, *member, *instance, *compartment, *grow, *apply)
	if err != nil {
		return err
	}
	if !request.Apply {
		wire, err := json.Marshal(request)
		if err == nil {
			_, err = fmt.Fprintf(output, "%s\n", wire)
		}
		return err
	}
	volumes, err := oci.NewOperatorMemberVolumes(oci.MemberVolumeConfig{Region: request.region,
		CompartmentID: request.Compartment, AvailabilityDomain: request.AvailabilityDomain, VPUsPerGB: request.VPUsPerGB})
	if err != nil {
		return err
	}
	if request.GrowGB != 0 {
		grown, err := volumes.Resize(ctx, request.Member, request.RecordedVolume, request.GrowGB)
		if err != nil {
			return err
		}
		_, err = fmt.Fprintf(output, "{\"step\":\"grown\",\"volume\":%q,\"volume_id\":%q,\"size_gb\":%d}\n", request.Volume, grown.ID, grown.SizeGB)
		return err
	}
	attachment, err := volumes.Ensure(ctx, oci.MemberVolumeRequest{Member: request.Member, InstanceID: request.Instance,
		SizeGB: request.SizeGB, VolumeID: request.RecordedVolume})
	if err != nil {
		return err
	}
	_, err = fmt.Fprintf(output, "{\"step\":\"attached\",\"volume\":%q,\"volume_id\":%q,\"attachment_id\":%q,\"instance\":%q,\"device\":%q}\n",
		request.Volume, attachment.VolumeID, attachment.ID, attachment.InstanceID, attachment.Device)
	return err
}

func resolveDataVolume(wire []byte, member, instance, compartment string, grow int64, apply bool) (dataVolumeRequest, error) {
	var plan cellPlan
	if err := json.Unmarshal(wire, &plan); err != nil {
		return dataVolumeRequest{}, fmt.Errorf("decode cell plan: %w", err)
	}
	cell := naming.RegionCell(plan.Cell)
	sizeGB, index, recorded := int64(0), 0, ""
	for _, host := range plan.Hosts {
		if !strings.HasPrefix(host.Slot, "member-") {
			continue
		}
		index++
		if name, err := cell.Server(naming.Member, index); err == nil && name == member {
			// A recorded volume is never recreated: see oci.MemberVolumeRequest.
			sizeGB, recorded = host.DataGB, plan.ResourceIDs.DataVolumes[host.Slot]
		}
	}
	if sizeGB == 0 {
		return dataVolumeRequest{}, fmt.Errorf("member %s is not a member host of the plan's cell with data_gb", member)
	}
	volume, err := naming.Data(member)
	if err != nil {
		return dataVolumeRequest{}, err
	}
	if compartment == "" {
		compartment = plan.ResourceIDs.WorkloadCompartment
	}
	if compartment == "" || plan.AvailabilityDomain == "" {
		return dataVolumeRequest{}, errors.New("data-volume needs the plan's availability_domain and a workload compartment (--compartment until the plan records it)")
	}
	step := "attach"
	if grow != 0 {
		step = "grow"
	}
	return dataVolumeRequest{Step: step, Apply: apply, Member: member, Volume: volume, SizeGB: sizeGB, GrowGB: grow, RecordedVolume: recorded,
		Instance: instance, Device: oci.MemberVolumeDevice, Compartment: compartment,
		AvailabilityDomain: plan.AvailabilityDomain, VPUsPerGB: plan.VPUsPerGB, region: oci.Region(plan.Cell)}, nil
}

func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

// Data returns the name of a member's retained data volume, e.g. ts-gru-1-data.
func Data(member string) (string, error) { return valid(member + "-data") }

// Validate accepts only a cell, node, server or data volume name of the
// scheme in a catalog region.
func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil

restore_volume_cli.text:
func runRestoreVolume(ctx context.Context, args []string, output io.Writer) error {
	flags := flag.NewFlagSet("terrabase restore-volume", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	planPath := flags.String("plan", "", "cell plan, for example deploy/oci-region/plan.json")
	member := flags.String("member", "", "member whose backup is restored, for example gru-1-db-1")
	scratch := flags.String("scratch-instance", "", "OCID of the running scratch instance, not a member host")
	backup := flags.String("backup", "", "backup OCID; defaults to the newest AVAILABLE backup of the member's volume")
	compartment := flags.String("compartment", "", "workload compartment OCID; defaults to the plan's resource_ids.workload_compartment")
	apply := flags.Bool("apply", false, "perform the OCI calls; without it only print the request")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if flags.NArg() != 0 || *planPath == "" || *member == "" || *scratch == "" {
		return errors.New("restore-volume requires --plan, --member and --scratch-instance")
	}
	wire, err := os.ReadFile(*planPath)
	if err != nil {
		return err
	}
	request, err := resolveDataVolume(wire, *member, *scratch, *compartment, 0, *apply)
	if err != nil {
		return err
	}
	// Print what --apply creates: the restored copy, at the restore device.
	request.Step, request.Backup = "restore", *backup
	request.Volume, request.Device = "restore-"+request.Volume, oci.RestoreVolumeDevice
	if !request.Apply {
		wire, err := json.Marshal(request)
		if err == nil {
			_, err = fmt.Fprintf(output, "%s\n", wire)
		}
		return err
	}
	volumes, err := oci.NewOperatorMemberVolumes(oci.MemberVolumeConfig{Region: request.region,
		CompartmentID: request.Compartment, AvailabilityDomain: request.AvailabilityDomain, VPUsPerGB: request.VPUsPerGB})
	if err != nil {
		return err
	}
	restored, err := volumes.Restore(ctx, oci.RestoreRequest{Member: request.Member, BackupID: request.Backup,
		ScratchInstanceID: request.Instance, SourceVolumeID: request.RecordedVolume})
	if err != nil {
		return err
	}
	_, err = fmt.Fprintf(output, "{\"step\":\"restored\",\"backup_id\":%q,\"volume_id\":%q,\"attachment_id\":%q,\"instance\":%q,\"device\":%q}\n",
		restored.BackupID, restored.VolumeID, restored.ID, restored.InstanceID, restored.Device)
	return err
}

live_clients.text:
func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

func OperatorConfig(region string) (*Factory, error) {
	return New(common.DefaultConfigProvider(), Options{Region: region})
}

func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)

func (f *Factory) Compute() (core.ComputeClient, error) {
	client, err := core.NewComputeClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Compute client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceCompute)
	return client, nil
}

func (f *Factory) Network() (core.VirtualNetworkClient, error) {
	client, err := core.NewVirtualNetworkClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI network client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceNetwork)
	return client, nil
}

func (f *Factory) Identity() (identity.IdentityClient, error) {
	client, err := identity.NewIdentityClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI identity client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceIdentity)
	return client, nil
}

live_ingress.text:
func observePeerIngress(ctx context.Context, compute core.ComputeClient, network core.VirtualNetworkClient,
	compartment, prefix string, port int,
) (peerIngressObservation, error) {
	var observation peerIngressObservation
	instances, err := compute.ListInstances(ctx, core.ListInstancesRequest{CompartmentId: &compartment,
		LifecycleState: core.InstanceLifecycleStateRunning, Limit: new(100)})
	if err != nil {
		return observation, fmt.Errorf("list peer instances: %w", err)
	}
	for _, instance := range instances.Items {
		if instance.DisplayName == nil || !strings.HasPrefix(*instance.DisplayName, prefix) {
			continue
		}
		// Keep matching instances even when no primary VNIC becomes a peer.
		observation.instances = append(observation.instances, instance)
		attachments, err := compute.ListVnicAttachments(ctx, core.ListVnicAttachmentsRequest{CompartmentId: &compartment, InstanceId: instance.Id})
		if err != nil {
			return observation, fmt.Errorf("list peer %s VNIC attachments: %w", *instance.DisplayName, err)
		}
		for _, attachment := range attachments.Items {
			if attachment.VnicId == nil || attachment.LifecycleState != core.VnicAttachmentLifecycleStateAttached {
				continue
			}
			vnic, err := network.GetVnic(ctx, core.GetVnicRequest{VnicId: attachment.VnicId})
			if err != nil {
				return observation, fmt.Errorf("get peer VNIC %s: %w", *attachment.VnicId, err)
			}
			if vnic.IsPrimary == nil || !*vnic.IsPrimary || vnic.PrivateIp == nil {
				continue
			}
			address, err := netip.ParseAddr(*vnic.PrivateIp)
			if err != nil {
				return observation, fmt.Errorf("parse peer %s private IP: %w", *instance.DisplayName, err)
			}
			observation.members = append(observation.members, peerIngressMember{
				name: *instance.DisplayName, faultDomain: *instance.FaultDomain, address: address, groups: vnic.NsgIds,
				instanceID: instance.Id, attachment: attachment, vnic: vnic.Vnic,
			})
		}
	}
	if len(observation.members) == 0 {
		return observation, nil
	}
	entries := make([]string, len(observation.members))
	for i, member := range observation.members {
		entries[i] = member.name + "=" + netip.AddrPortFrom(member.address, uint16(port)).String()
	}
	observation.peers = strings.Join(entries, ",")
	observation.parsed, err = ParsePeers(observation.peers)
	if err != nil {
		return observation, fmt.Errorf("the hosts give an invalid peer list: %w", err)
	}
	observation.rules = map[string][]core.SecurityRule{}
	for _, member := range observation.members {
		for _, group := range member.groups {
			if _, read := observation.rules[group]; read {
				continue
			}
			response, err := network.ListNetworkSecurityGroupSecurityRules(ctx, core.ListNetworkSecurityGroupSecurityRulesRequest{
				NetworkSecurityGroupId: &group, Direction: core.ListNetworkSecurityGroupSecurityRulesDirectionIngress, Limit: new(100)})
			if err != nil {
				return observation, fmt.Errorf("list peer NSG %s ingress: %w", group, err)
			}
			observation.rules[group] = response.Items
		}
	}
	for _, receiver := range observation.members {
		for _, sender := range observation.members {
			if sender.name != receiver.name {
				observation.pairs = append(observation.pairs, peerIngressAssessment{
					sender: sender.name, receiver: receiver.name,
					allowed: peerPortOpen(receiver.groups, observation.rules, sender.address, sender.groups, port),
				})
			}
		}
	}
	return observation, nil
}

func peerPortOpen(receiver []string, rules map[string][]core.SecurityRule, sender netip.Addr, senderGroups []string, port int) bool {
	for _, group := range receiver {
		for _, rule := range rules[group] {
			if rule.Protocol == nil || (*rule.Protocol != "6" && *rule.Protocol != "all") || rule.Source == nil {
				continue
			}
			if *rule.Protocol == "6" && rule.TcpOptions != nil && rule.TcpOptions.DestinationPortRange != nil {
				ports := rule.TcpOptions.DestinationPortRange
				if ports.Min == nil || ports.Max == nil || *ports.Min > port || *ports.Max < port {
					continue
				}
			}
			switch rule.SourceType {
			case core.SecurityRuleSourceTypeNetworkSecurityGroup:
				if slices.Contains(senderGroups, *rule.Source) {
					return true
				}
			default:
				if prefix, err := netip.ParsePrefix(*rule.Source); err == nil && prefix.Contains(sender) {
					return true
				}
			}
		}
	}
	return false
}

func liveEnv(name, fallback string) string {
	if value := os.Getenv(name); value != "" {
		return value
	}
	return fallback
}

func ParsePeers(raw string) ([]Peer, error) {
	if raw == "" {
		return nil, fmt.Errorf("%s is required", EnvPeers)
	}
	entries := strings.Split(raw, ",")
	if len(entries) > 64 {
		return nil, fmt.Errorf("%s lists more than 64 members", EnvPeers)
	}
	peers := make([]Peer, 0, len(entries))
	for _, entry := range entries {
		name, address, found := strings.Cut(entry, "=")
		addrPort, err := netip.ParseAddrPort(address)
		if !found || !nameRE.MatchString(name) || err != nil || addrPort.String() != address ||
			addrPort.Port() == 0 || !addrPort.Addr().IsValid() || addrPort.Addr().IsUnspecified() {
			return nil, fmt.Errorf("%s entry %q is not name=ip:port", EnvPeers, entry)
		}
		if addrPort.Addr().Zone() != "" || addrPort.Addr().IsLinkLocalUnicast() || addrPort.Addr().IsLinkLocalMulticast() {
			return nil, fmt.Errorf("%s entry %q: zone identifiers and link-local addresses are not supported", EnvPeers, entry)
		}
		if slices.ContainsFunc(peers, func(p Peer) bool { return p.Name == name || p.Address == addrPort }) {
			return nil, fmt.Errorf("%s repeats member %q or its address", EnvPeers, name)
		}
		peers = append(peers, Peer{Name: name, Address: addrPort})
	}
	return peers, nil
}

func parsePort(raw string) (int, error) {
	port, err := strconv.Atoi(raw)
	if err != nil || port < 1 || port > 65535 || strconv.Itoa(port) != raw {
		return 0, errors.New("must be a port between 1 and 65535")
	}
	return port, nil

